from collections import Counter

class Solution:
    def findEvenNumbers(self, digits: list[int]) -> list[int]:
        available = Counter(digits)
        ans = []

        for num in range(100, 1000, 2):
            d1, rem = divmod(num, 100)
            d2, d3 = divmod(rem, 10)

            need = Counter([d1, d2, d3])
            if all(available[d] >= count for d, count in need.items()):
                ans.append(num)

        return ans

#include <vector>

class Solution {
public:
    std::vector<int> findEvenNumbers(std::vector<int>& digits) {
        std::vector<int> count(10, 0);
        for (int d : digits) count[d]++;

        std::vector<int> ans;
        for (int num = 100; num < 1000; num += 2) {
            int d1 = num / 100;
            int d2 = (num / 10) % 10;
            int d3 = num % 10;

            std::vector<int> need(10, 0);
            need[d1]++;
            need[d2]++;
            need[d3]++;

            bool ok = true;
            for (int d = 0; d < 10; ++d) {
                if (need[d] > count[d]) {
                    ok = false;
                    break;
                }
            }
            if (ok) ans.push_back(num);
        }
        return ans;
    }
};

import java.util.ArrayList;
import java.util.List;

class Solution {
    public int[] findEvenNumbers(int[] digits) {
        int[] count = new int[10];
        for (int d : digits) count[d]++;

        List<Integer> list = new ArrayList<>();
        for (int num = 100; num < 1000; num += 2) {
            int d1 = num / 100;
            int d2 = (num / 10) % 10;
            int d3 = num % 10;

            int[] need = new int[10];
            need[d1]++;
            need[d2]++;
            need[d3]++;

            boolean ok = true;
            for (int d = 0; d < 10; d++) {
                if (need[d] > count[d]) {
                    ok = false;
                    break;
                }
            }
            if (ok) list.add(num);
        }

        int[] ans = new int[list.size()];
        for (int i = 0; i < list.size(); i++) ans[i] = list.get(i);
        return ans;
    }
}

